import {scientificCalculate,scientificDisplay} from './scientific-core.mjs';
import {e,result,error,clearOutput} from './ui.mjs';
const functions=[
 ['sin','sin(','Sine in degrees'],['cos','cos(','Cosine in degrees'],['tan','tan(','Tangent in degrees'],['sin⁻¹','asin(','Inverse sine · degrees'],['cos⁻¹','acos(','Inverse cosine · degrees'],['tan⁻¹','atan(','Inverse tangent · degrees'],
 ['√x','sqrt(','Square root'],['∛x','cbrt(','Cube root'],['x²','square','Square selection or expression'],['x³','cube','Cube selection or expression'],['xʸ','^','Raise to a power'],['1/x','reciprocal','Reciprocal of selection or expression'],
 ['ln','ln(','Natural logarithm'],['log','log(','Base-10 logarithm'],['10ˣ','tenpower','Ten to the power'],['eˣ','exp(','Exponential function'],['n!','factorial','Factorial'],['|x|','abs(','Absolute value'],
 ['π','pi','Pi'],['e','e','Euler constant'],['Ans','ans','Last answer · this session only'],['mod',' mod ','Remainder'],['(', '(','Open parenthesis'],[')',')','Close parenthesis']
];
const numbers=[['AC','clear','Clear all'],['⌫','backspace','Backspace'],['%','%','Percent · divide by 100'],['÷','/','Divide'],['7','7'],['8','8'],['9','9'],['×','*','Multiply'],['4','4'],['5','5'],['6','6'],['−','-','Subtract'],['1','1'],['2','2'],['3','3'],['+','+','Add'],['±','negate','Change sign'],['0','0'],['.','.','Decimal point'],['=','equals','Calculate (=)']];
function keys(items){return items.map(([label,value,title])=>`<button type="${value==='equals'?'submit':'button'}" class="calc-key ${['clear','backspace'].includes(value)?'calc-utility':['/','*','-','+','equals'].includes(value)?'calc-operator':''} ${value==='equals'?'calc-equals':''}" data-calc-key="${e(value)}" aria-label="${e(title||label)}" title="${e(title||label)}">${e(label)}</button>`).join('');}
export function setupScientific(tool,mount,out){
 let answer,justCalculated=false,disposed=false;
 mount.classList.add('scientific-calculator');mount.innerHTML=`<div class="calc-heading"><div><span class="eyebrow">A LITTLE ROOM FOR BIGGER NUMBERS</span><h2>Scientific calculator</h2></div><span class="calc-degree" aria-label="Angle unit: degrees">DEG <small>Degrees</small></span></div><form autocomplete="off"><label class="field full"><span>Expression</span><input class="calc-expression" name="calculation-expression" type="text" value="sin(30)" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" maxlength="4000" aria-describedby="calc-help calc-status" enterkeyhint="go"></label><div class="calc-key-panels"><section aria-label="Scientific function buttons"><div class="calc-key-label"><strong>Scientific functions</strong><span>DEG</span></div><div class="calc-functions">${keys(functions)}</div></section><section aria-label="Number and operator buttons"><div class="calc-key-label"><strong>Numbers & operators</strong><span>Enter =</span></div><div class="calc-numbers">${keys(numbers)}</div></section></div><p class="calc-status" id="calc-status" role="status">Use the buttons or type an expression. Enter calculates; Esc clears.</p><div class="form-error"></div><button type="button" class="btn secondary small calc-view-result" data-calc-view>View result ↓</button></form><p class="form-note" id="calc-help">sin, cos and tan take degrees; inverse trig returns degrees. Example: sin(30) = 0.5. % divides by 100; mod finds a remainder. Use × between values. Display rounds to 12 significant digits.</p><details class="calc-reference"><summary>More typed functions & examples</summary><p>round(2.6), floor(2.9), ceil(2.1), sqrt(144), cbrt(27), abs(-5), log(100), ln(e), 2^3 and 5!. A real logarithm needs a positive value. tan(90) is undefined. Ans keeps only the last answer in this page session.</p></details>`;
 const f=mount.querySelector('form'),input=f.querySelector('input'),status=f.querySelector('#calc-status'),err=f.querySelector('.form-error');
 const pending=()=>{clearOutput(out);out.removeAttribute('data-result-stale');out.innerHTML='<div class="result-placeholder"><span class="calc-degree">DEG</span><strong>Ready to calculate.</strong><span>Press = or Enter to see the answer for your current expression.</span></div>';err.innerHTML='';justCalculated=false;status.textContent='Expression changed. Press = or Enter to calculate.';};
 function compute(){if(disposed)return;err.innerHTML='';try{const expression=input.value.trim();if(!expression){pending();status.textContent='Enter an expression to begin.';return;}const value=scientificCalculate(expression,{answer});answer=value;result(out,{label:'Answer · DEG',value:scientificDisplay(value),details:[['Expression',expression],['Angle unit','Degrees (DEG)']],copy:scientificDisplay(value),note:'Angles are measured in degrees. The display rounds to 12 significant digits.'});status.textContent='Calculated in degrees. Edit the expression or start another calculation.';justCalculated=true;}catch(ex){clearOutput(out);out.removeAttribute('data-result-stale');out.innerHTML='<div class="calc-error-result"><span class="calc-degree">DEG</span><h2>Check this expression.</h2><p role="alert">'+e(ex.message)+'</p></div>';error(err,ex.message);status.textContent='No answer was produced. Check the expression.';justCalculated=false;}}
 function update(value,start,end){if(input.value.length-(end-start)+value.length>4000){error(err,'Use an expression up to 4,000 characters.');return;}input.setRangeText(value,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}
 function press(key){let start=input.selectionStart??input.value.length,end=input.selectionEnd??start,selected=input.value.slice(start,end);
  if(key==='clear'){answer=undefined;input.value='';pending();status.textContent='Cleared. Enter a new expression.';input.focus();return;}
  if(key==='backspace'){update('',start===end?Math.max(0,start-1):start,end);return;}
  if(['square','cube','reciprocal','factorial','negate','tenpower'].includes(key)){const value=selected||input.value||'0',wrap={square:`(${value})^2`,cube:`(${value})^3`,reciprocal:`1/(${value})`,factorial:`(${value})!`,negate:`-(${value})`,tenpower:`10^(${value})`}[key];update(wrap,selected?start:0,selected?end:input.value.length);return;}
  if(justCalculated){if(['+','-','*','/','^',' mod ','%'].includes(key)){input.value='ans';start=end=3;}else{input.value='';start=end=0;selected='';}}
  let value=key;
  if(key.endsWith('(')&&key!=='('){if(selected)value=key+selected+')';const before=input.value.slice(0,start);if(!selected&&/[\d.)!%]$|(?:pi|ans|e)$/i.test(before))value='*'+value;}
  else if(['pi','e','ans','('].includes(key)&&/[\d.)!%]$|(?:pi|ans|e)$/i.test(input.value.slice(0,start)))value='*'+key;
  update(value,start,end);
 }
 input.addEventListener('input',pending);f.onsubmit=ev=>{ev.preventDefault();compute();};f.onclick=ev=>{const key=ev.target.closest('[data-calc-key]');if(key&&key.dataset.calcKey!=='equals')press(key.dataset.calcKey);};input.onkeydown=ev=>{if(ev.key==='Escape'){ev.preventDefault();press('clear');}else if(ev.key==='='&&!ev.ctrlKey&&!ev.metaKey){ev.preventDefault();compute();}};f.querySelector('[data-calc-view]').onclick=()=>out.scrollIntoView({block:'start',behavior:document.body.classList.contains('motion-paused')?'auto':'smooth'});compute();return()=>{disposed=true;};
}
